// Merge the channel catalogues into the main ones, then rebuild the %s/%d
// templates (package variables are initialised before init functions run).
func init() {
	for k, v := range frChannels {
		fr[k] = v
	}
	for k, v := range esChannels {
		es[k] = v
	}
	templates = buildTemplates()
}
